     1→/**
     2→ * CLAUDELang v6.0 통합 시스템
     3→ *
     4→ * 기능:
     5→ * 1. JSON 파일 읽기
     6→ * 2. 컴파일러를 통한 VT 바이트코드 생성
     7→ * 3. VT 런타임에서 실행
     8→ * 4. 결과값 추출 및 검증
     9→ */
    10→
    11→const fs = require('fs');
    12→const path = require('path');
    13→const CLAUDELangCompiler = require('./compiler.js');
    14→
    15→/**
    16→ * 향상된 VT 런타임
    17→ * Array.map, Array.filter 등의 고차 함수 지원
    18→ */
    19→class VTRuntime {
    20→  constructor() {
    21→    this.scope = new Map();
    22→    this.output = [];
    23→    this.executionTime = 0;
    24→    this.memoryUsage = 0;
    25→    this.instructionCount = 0;
    26→    this.lastResult = undefined;
    27→  }
    28→
    29→  /**
    30→   * VT 코드 실행
    31→   */
    32→  execute(vtCode) {
    33→    const startTime = Date.now();
    34→    const startMem = process.memoryUsage().heapUsed;
    35→
    36→    try {
    37→      const lines = vtCode.split('\n').filter(line => {
    38→        return line.trim() && !line.trim().startsWith(';');
    39→      });
    40→
    41→      for (const line of lines) {
    42→        this.executeSExpression(line.trim());
    43→        this.instructionCount++;
    44→      }
    45→
    46→      const endTime = Date.now();
    47→      const endMem = process.memoryUsage().heapUsed;
    48→
    49→      this.executionTime = endTime - startTime;
    50→      this.memoryUsage = Math.max(0, (endMem - startMem) / 1024 / 1024);
    51→
    52→      return {
    53→        success: true,
    54→        output: this.output,
    55→        result: this.lastResult,
    56→        executionTime: this.executionTime,
    57→        memoryUsage: this.memoryUsage,
    58→        instructionCount: this.instructionCount,
    59→      };
    60→    } catch (error) {
    61→      return {
    62→        success: false,
    63→        output: this.output,
    64→        error: error.message,
    65→        executionTime: Date.now() - startTime,
    66→      };
    67→    }
    68→  }
    69→
    70→  /**
    71→   * S-expression 실행
    72→   */
    73→  executeSExpression(expr) {
    74→    // 기본 변수 선언: (define name value)
    75→    const defineMatch = expr.match(/^\(define\s+(\w+)\s+(.+)\)$/);
    76→    if (defineMatch) {
    77→      const [, name, valueExpr] = defineMatch;
    78→      this.lastResult = this.evaluateExpression(valueExpr);
    79→      this.scope.set(name, this.lastResult);
    80→      return;
    81→    }
    82→
    83→    // 함수 호출: (call function arg1 arg2 ...)
    84→    const callMatch = expr.match(/^\(call\s+(\S+)\s*(.*)\)$/);
    85→    if (callMatch) {
    86→      const [, funcName, argsStr] = callMatch;
    87→      this.lastResult = this.executeFunction(funcName, argsStr);
    88→      return;
    89→    }
    90→
    91→    // if 조건: (if condition then-block else-block)
    92→    const ifMatch = expr.match(/^\(if\s+(.+?)\s+\(do\s+(.+?)\)\s+\(do\s+(.+?)\)\)$/);
    93→    if (ifMatch) {
    94→      const [, condExpr, thenExpr, elseExpr] = ifMatch;
    95→      const condition = this.evaluateExpression(condExpr);
    96→      if (condition) {
    97→        this.executeSExpression(thenExpr);
    98→      } else {
    99→        this.executeSExpression(elseExpr);
   100→      }
   101→      return;
   102→    }
   103→
   104→    // for 루프: (for iterator range body) 또는 (for iterator varname (do body))
   105→    const forMatch = expr.match(/^\(for\s+(\w+)\s+(.+?)\s+\(do\s+(.+)\)\)$/);
   106→    if (forMatch) {
   107→      const [, iterator, rangeExpr, bodyExpr] = forMatch;
   108→
   109→      // range 평가: 배열 리터럴 또는 변수 참조
   110→      let elements = [];
   111→      if (rangeExpr.startsWith('(array')) {
   112→        // (array 1 2 3) 형태
   113→        const arrayMatch = rangeExpr.match(/^\(array\s+([\d\s]+)\)$/);
   114→        if (arrayMatch) {
   115→          elements = arrayMatch[1].trim().split(/\s+/).map(e => Number(e));
   116→        }
   117→      } else {
   118→        // 변수 참조
   119→        const value = this.evaluateExpression(rangeExpr);
   120→        if (Array.isArray(value)) {
   121→          elements = value;
   122→        }
   123→      }
   124→
   125→      for (const elem of elements) {
   126→        this.scope.set(iterator, elem);
   127→        this.executeSExpression(bodyExpr);
   128→      }
   129→      return;
   130→    }
   131→  }
   132→
   133→  /**
   134→   * 식 평가
   135→   */
   136→  evaluateExpression(expr) {
   137→    expr = expr.trim();
   138→
   139→    // 문자열 리터럴
   140→    if (expr.startsWith('"') && expr.endsWith('"')) {
   141→      return expr.slice(1, -1);
   142→    }
   143→
   144→    // 숫자 리터럴
   145→    if (!isNaN(Number(expr))) {
   146→      return Number(expr);
   147→    }
   148→
   149→    // 참조 (변수명)
   150→    if (this.scope.has(expr)) {
   151→      return this.scope.get(expr);
   152→    }
   153→
   154→    // 배열: (array elem1 elem2 ...)
   155→    if (expr.startsWith('(array')) {
   156→      const elementsStr = expr.slice(7, -1).trim();
   157→      if (!elementsStr) return [];
   158→      return elementsStr.split(/\s+/).map(e => this.evaluateExpression(e));
   159→    }
   160→
   161→    // 객체: (object (key1 val1) (key2 val2) ...)
   162→    if (expr.startsWith('(object')) {
   163→      const obj = {};
   164→      const propsStr = expr.slice(8, -1);
   165→      const propMatches = propsStr.match(/\("(\w+)"\s+([^)]+)\)/g);
   166→      if (propMatches) {
   167→        propMatches.forEach(prop => {
   168→          const match = prop.match(/\("(\w+)"\s+(.+)\)/);
   169→          if (match) {
   170→            obj[match[1]] = this.evaluateExpression(match[2]);
   171→          }
   172→        });
   173→      }
   174→      return obj;
   175→    }
   176→
   177→    // 산술 연산: (+ a b), (- a b), (* a b), (/ a b), (% a b)
   178→    const arithmeticOp = expr.match(/^\(([+\-*/%])/);
   179→    if (arithmeticOp) {
   180→      const operator = arithmeticOp[1];
   181→      const content = expr.slice(operator.length + 2, -1).trim();
   182→
   183→      // Split by the last space that's not inside parentheses
   184→      let depth = 0;
   185→      let splitIdx = -1;
   186→      for (let i = content.length - 1; i >= 0; i--) {
   187→        if (content[i] === ')') depth++;
   188→        else if (content[i] === '(') depth--;
   189→        else if (content[i] === ' ' && depth === 0) {
   190→          splitIdx = i;
   191→          break;
   192→        }
   193→      }
   194→
   195→      if (splitIdx > 0) {
   196→        const left = content.substring(0, splitIdx);
   197→        const right = content.substring(splitIdx + 1);
   198→        const leftVal = this.evaluateExpression(left);
   199→        const rightVal = this.evaluateExpression(right);
   200→        switch (operator) {
   201→          case '+': return leftVal + rightVal;
   202→          case '-': return leftVal - rightVal;
   203→          case '*': return leftVal * rightVal;
   204→          case '/': return leftVal / rightVal;
   205→          case '%': return leftVal % rightVal;
   206→        }
   207→      }
   208→    }
   209→
   210→    // 비교 연산: (== a b), (!= a b), (< a b), (> a b), (<= a b), (>= a b)
   211→    const comparisonMatch = expr.match(/^\((==|!=|<|>|<=|>=)\s+(.+)\s+([^()]*|.+)\)$/);
   212→    if (comparisonMatch) {
   213→      const compOp = expr.match(/^\((==|!=|<|>|<=|>=)/);
   214→      if (compOp) {
   215→        const operator = compOp[1];
   216→        // Extract left and right operands by finding the split point
   217→        const content = expr.slice(operator.length + 2, -1).trim();
   218→
   219→        // Split by the last space that's not inside parentheses
   220→        let depth = 0;
   221→        let splitIdx = -1;
   222→        for (let i = content.length - 1; i >= 0; i--) {
   223→          if (content[i] === ')') depth++;
   224→          else if (content[i] === '(') depth--;
   225→          else if (content[i] === ' ' && depth === 0) {
   226→            splitIdx = i;
   227→            break;
   228→          }
   229→        }
   230→
   231→        if (splitIdx > 0) {
   232→          const left = content.substring(0, splitIdx);
   233→          const right = content.substring(splitIdx + 1);
   234→          const leftVal = this.evaluateExpression(left);
   235→          const rightVal = this.evaluateExpression(right);
   236→          switch (operator) {
   237→            case '==': return leftVal === rightVal;
   238→            case '!=': return leftVal !== rightVal;
   239→            case '<': return leftVal < rightVal;
   240→            case '>': return leftVal > rightVal;
   241→            case '<=': return leftVal <= rightVal;
   242→            case '>=': return leftVal >= rightVal;
   243→          }
   244→        }
   245→      }
   246→    }
   247→
   248→    // 속성 접근: (property obj "prop")
   249→    const propertyMatch = expr.match(/^\(property\s+(.+?)\s+"(\w+)"\)$/);
   250→    if (propertyMatch) {
   251→      const [, objExpr, propName] = propertyMatch;
   252→      const obj = this.evaluateExpression(objExpr);
   253→      if (obj && typeof obj === 'object' && propName in obj) {
   254→        return obj[propName];
   255→      }
   256→      return null;
   257→    }
   258→
   259→    // 인덱스 접근: (index array idx)
   260→    const indexMatch = expr.match(/^\(index\s+(.+?)\s+(.+)\)$/);
   261→    if (indexMatch) {
   262→      const [, arrayExpr, indexExpr] = indexMatch;
   263→      const array = this.evaluateExpression(arrayExpr);
   264→      const index = this.evaluateExpression(indexExpr);
   265→      if (Array.isArray(array) && typeof index === 'number') {
   266→        return array[Math.floor(index)];
   267→      }
   268→      return null;
   269→    }
   270→
   271→    // 함수 호출: (call function arg1 arg2 ...)
   272→    const callExpr = expr.match(/^\(call\s+(\S+)\s*(.*)\)$/);
   273→    if (callExpr) {
   274→      const [, funcName, argsStr] = callExpr;
   275→      return this.executeFunction(funcName, argsStr);
   276→    }
   277→
   278→    // 함수: (fn (params) body)
   279→    if (expr.startsWith('(fn')) {
   280→      // 람다 함수 반환 (실제 평가는 나중에)
   281→      return { type: 'lambda', expr: expr };
   282→    }
   283→
   284→    return null;
   285→  }
   286→
   287→  /**
   288→   * 함수 실행
   289→   */
   290→  executeFunction(funcName, argsStr) {
   291→    const args = this.parseArguments(argsStr);
   292→
   293→    switch (funcName) {
   294→      case 'print':
   295→        if (args.length > 0) {
   296→          this.output.push(String(args[0]));
   297→        }
   298→        return args[0];
   299→
   300→      case 'IO.print_array':
   301→        if (args.length > 0 && Array.isArray(args[0])) {
   302→          const result = args[0];
   303→          this.output.push(JSON.stringify(result));
   304→          return result;
   305→        }
   306→        return null;
   307→
   308→      case 'Array.map': {
   309→        if (args.length >= 2 && Array.isArray(args[0]) && args[1].type === 'lambda') {
   310→          const array = args[0];
   311→          const lambdaExpr = args[1].expr;
   312→
   313→          // 람다 파라미터 추출: (fn (param) body)
   314→          const paramMatch = lambdaExpr.match(/\(fn\s+\((\w+)\)\s+(.+)\)/);
   315→          if (paramMatch) {
   316→            const [, paramName, bodyExpr] = paramMatch;
   317→            const result = [];
   318→            for (const elem of array) {
   319→              this.scope.set(paramName, elem);
   320→              result.push(this.evaluateExpression(bodyExpr));
   321→            }
   322→            return result;
   323→          }
   324→        }
   325→        return args[0];
   326→      }
   327→
   328→      case 'Array.filter': {
   329→        if (args.length >= 2 && Array.isArray(args[0]) && args[1].type === 'lambda') {
   330→          const array = args[0];
   331→          const lambdaExpr = args[1].expr;
   332→
   333→          const paramMatch = lambdaExpr.match(/\(fn\s+\((\w+)\)\s+(.+)\)/);
   334→          if (paramMatch) {
   335→            const [, paramName, bodyExpr] = paramMatch;
   336→            const result = [];
   337→            for (const elem of array) {
   338→              this.scope.set(paramName, elem);
   339→              if (this.evaluateExpression(bodyExpr)) {
   340→                result.push(elem);
   341→              }
   342→            }
   343→            return result;
   344→          }
   345→        }
   346→        return args[0];
   347→      }
   348→
   349→      case 'Array.reduce': {
   350→        if (args.length >= 3 && Array.isArray(args[0]) && args[1].type === 'lambda') {
   351→          const array = args[0];
   352→          const lambdaExpr = args[1].expr;
   353→          let accumulator = args[2];
   354→
   355→          const paramMatch = lambdaExpr.match(/\(fn\s+\((\w+)\s+(\w+)\)\s+(.+)\)/);
   356→          if (paramMatch) {
   357→            const [, accName, elemName, bodyExpr] = paramMatch;
   358→            for (const elem of array) {
   359→              this.scope.set(accName, accumulator);
   360→              this.scope.set(elemName, elem);
   361→              accumulator = this.evaluateExpression(bodyExpr);
   362→            }
   363→            return accumulator;
   364→          }
   365→        }
   366→        return args[2];
   367→      }
   368→
   369→      case 'String.split': {
   370→        if (args.length >= 2 && typeof args[0] === 'string' && typeof args[1] === 'string') {
   371→          return args[0].split(args[1]);
   372→        }
   373→        return args[0];
   374→      }
   375→
   376→      case 'String.join': {
   377→        if (args.length >= 2 && Array.isArray(args[0]) && typeof args[1] === 'string') {
   378→          return args[0].join(args[1]);
   379→        }
   380→        return '';
   381→      }
   382→
   383→      case 'String.upper': {
   384→        if (args.length >= 1 && typeof args[0] === 'string') {
   385→          return args[0].toUpperCase();
   386→        }
   387→        return args[0];
   388→      }
   389→
   390→      case 'String.lower': {
   391→        if (args.length >= 1 && typeof args[0] === 'string') {
   392→          return args[0].toLowerCase();
   393→        }
   394→        return args[0];
   395→      }
   396→
   397→      case 'String.trim': {
   398→        if (args.length >= 1 && typeof args[0] === 'string') {
   399→          return args[0].trim();
   400→        }
   401→        return args[0];
   402→      }
   403→
   404→      case 'String.concat': {
   405→        // 모든 인수를 문자열로 연결
   406→        return args.map(arg => String(arg)).join('');
   407→      }
   408→
   409→      case 'Math.sqrt':
   410→        return Math.sqrt(Number(args[0]));
   411→
   412→      case 'Math.pow':
   413→        return Math.pow(Number(args[0]), Number(args[1]));
   414→
   415→      case 'Math.abs':
   416→        return Math.abs(Number(args[0]));
   417→
   418→      case 'Array.find': {
   419→        if (args.length >= 2 && Array.isArray(args[0]) && args[1].type === 'lambda') {
   420→          const array = args[0];
   421→          const lambdaExpr = args[1].expr;
   422→
   423→          const paramMatch = lambdaExpr.match(/\(fn\s+\((\w+)\)\s+(.+)\)/);
   424→          if (paramMatch) {
   425→            const [, paramName, bodyExpr] = paramMatch;
   426→            for (const elem of array) {
   427→              this.scope.set(paramName, elem);
   428→              if (this.evaluateExpression(bodyExpr)) {
   429→                return elem;
   430→              }
   431→            }
   432→          }
   433→        }
   434→        return null;
   435→      }
   436→
   437→      case 'JSON.stringify':
   438→        return JSON.stringify(args[0]);
   439→
   440→      case 'JSON.parse':
   441→        try {
   442→          return JSON.parse(args[0]);
   443→        } catch {
   444→          return null;
   445→        }
   446→
   447→      default:
   448→        this.output.push(`[${funcName}] 함수 호출`);
   449→        return null;
   450→    }
   451→  }
   452→
   453→  /**
   454→   * 인수 파싱
   455→   */
   456→  parseArguments(argsStr) {
   457→    if (!argsStr.trim()) return [];
   458→
   459→    const args = [];
   460→    let current = '';
   461→    let depth = 0;
   462→    let inQuotes = false;
   463→
   464→    for (const char of argsStr) {
   465→      if (char === '"') {
   466→        inQuotes = !inQuotes;
   467→        current += char;
   468→      } else if (char === '(' && !inQuotes) {
   469→        depth++;
   470→        current += char;
   471→      } else if (char === ')' && !inQuotes) {
   472→        depth--;
   473→        current += char;
   474→      } else if (char === ' ' && !inQuotes && depth === 0) {
   475→        if (current) args.push(current);
   476→        current = '';
   477→      } else {
   478→        current += char;
   479→      }
   480→    }
   481→    if (current) args.push(current);
   482→
   483→    return args.map(arg => this.evaluateExpression(arg));
   484→  }
   485→}
   486→
   487→/**
   488→ * CLAUDELang 메인 클래스
   489→ * JSON 파일 읽기 → 컴파일 → 실행 → 결과 반환
   490→ */
   491→class CLAUDELang {
   492→  constructor() {
   493→    this.compiler = new CLAUDELangCompiler();
   494→    this.runtime = new VTRuntime();
   495→  }
   496→
   497→  /**
   498→   * 파일 실행
   499→   */
   500→  runFile(jsonFilePath) {
   501→    try {
   502→      // 1. JSON 파일 읽기
   503→      const fileContent = fs.readFileSync(jsonFilePath, 'utf-8');
   504→      const program = JSON.parse(fileContent);
   505→
   506→      // 2. 컴파일
   507→      const compileResult = this.compiler.compile(program);
   508→      if (!compileResult.success) {
   509→        return {
   510→          success: false,
   511→          error: `Compilation failed: ${compileResult.errors.join(', ')}`,
   512→        };
   513→      }
   514→
   515→      // 3. VT 런타임에서 실행
   516→      this.runtime = new VTRuntime(); // 런타임 초기화
   517→      const executionResult = this.runtime.execute(compileResult.code);
   518→
   519→      // 4. 결과 반환
   520→      return {
   521→        success: executionResult.success,
   522→        output: executionResult.output,
   523→        result: executionResult.result,
   524→        executionTime: executionResult.executionTime,
   525→        memoryUsage: executionResult.memoryUsage,
   526→        instructionCount: executionResult.instructionCount,
   527→        error: executionResult.error,
   528→      };
   529→    } catch (error) {
   530→      return {
   531→        success: false,
   532→        error: error.message,
   533→      };
   534→    }
   535→  }
   536→
   537→  /**
   538→   * 프로그램 문자열 실행
   539→   */
   540→  runProgram(program) {
   541→    try {
   542→      // 1. 컴파일
   543→      const compileResult = this.compiler.compile(program);
   544→      if (!compileResult.success) {
   545→        return {
   546→          success: false,
   547→          error: `Compilation failed: ${compileResult.errors.join(', ')}`,
   548→        };
   549→      }
   550→
   551→      // 2. 실행
   552→      this.runtime = new VTRuntime();
   553→      const executionResult = this.runtime.execute(compileResult.code);
   554→
   555→      return {
   556→        success: executionResult.success,
   557→        output: executionResult.output,
   558→        result: executionResult.result,
   559→        executionTime: executionResult.executionTime,
   560→        memoryUsage: executionResult.memoryUsage,
   561→        instructionCount: executionResult.instructionCount,
   562→        error: executionResult.error,
   563→      };
   564→    } catch (error) {
   565→      return {
   566→        success: false,
   567→        error: error.message,
   568→      };
   569→    }
   570→  }
   571→
   572→  /**
   573→   * 예제 디렉토리의 모든 파일 실행
   574→   */
   575→  runExamplesDirectory(examplesDir) {
   576→    const results = {};
   577→    const files = fs.readdirSync(examplesDir)
   578→      .filter(f => f.endsWith('.json'))
   579→      .sort();
   580→
   581→    for (const file of files) {
   582→      const filePath = path.join(examplesDir, file);
   583→      const name = path.basename(file, '.json');
   584→      results[name] = this.runFile(filePath);
   585→    }
   586→
   587→    return results;
   588→  }
   589→}
   590→
   591→// 내보내기
   592→if (typeof module !== 'undefined' && module.exports) {
   593→  module.exports = { CLAUDELang, VTRuntime };
   594→}
