   119→  validate(obj) {
   120→    if (!obj.version) {
   121→      throw new Error("Missing 'version' field");
   122→    }
   123→
   124→    if (obj.version !== "6.0") {
   125→      throw new Error(`Unsupported version: ${obj.version}`);
   126→    }
