   132→    obj.instructions.forEach((instr, idx) => {
   133→      if (!instr.type) {
   134→        throw new Error(`Instruction at line ${idx} missing 'type'`);
   135→      }
   136→
   137→      switch (instr.type) {
   138→        case "var":
   139→          if (!instr.name || !instr.value_type) {
   140→            throw new Error(`VarDeclaration at line ${idx} missing required fields`);
   141→          }
   142→          break;
