   144→        case "call":
   145→          if (!instr.function || !Array.isArray(instr.args)) {
   146→            throw new Error(`CallInstruction at line ${idx} missing required fields`);
   147→          }
   148→          break;
   149→
   150→        case "condition":
   151→          if (!instr.test || !Array.isArray(instr.then)) {
   152→            throw new Error(`ConditionInstruction at line ${idx} missing required fields`);
   153→          }
   154→          break;
