   156→        case "loop":
   157→          if (!instr.iterator || !instr.range || !Array.isArray(instr.body)) {
   158→            throw new Error(`LoopInstruction at line ${idx} missing required fields`);
   159→          }
   160→          break;
   161→
   162→        case "arithmetic":
   163→          if (!instr.operator) {
   164→            throw new Error(`ArithmeticInstruction at line ${idx} missing operator`);
   165→          }
   166→          break;
   167→
