   202→            throw new Error(
   203→              `Cannot assign ${exprType} to ${instr.value_type}`
   204→            );
   205→          }
   206→        }
   207→        break;
   208→
   209→      case "call":
   210→        // 함수 존재 여부 확인
   211→        if (!this.vtFunctions.has(instr.function)) {
   212→          throw new Error(`Unknown function: ${instr.function}`);
   213→        }
   214→
   215→        // 함수 시그니처 검사
   216→        const signature = this.vtFunctions.get(instr.function);
   217→        const minParams = signature.minParams || signature.params.length;
   218→        const maxParams = signature.params.length;
   219→
   220→        if (instr.args.length < minParams || instr.args.length > maxParams) {
   221→          throw new Error(
   222→            `${instr.function} expects ${minParams}-${maxParams} arguments, got ${instr.args.length}`
   223→          );
   224→        }
   225→
   226→        // 반환값을 scope에 추가
   227→        if (instr.assign_to) {
   228→          this.scope.set(instr.assign_to, signature.returnType);
   229→        }
   230→        break;
   231→
   232→      case "arithmetic":
   233→        // 산술 연산 타입 추론
   234→        const arithType = this.inferType({ type: "arithmetic" });
   235→        if (instr.assign_to) {
   236→          this.scope.set(instr.assign_to, arithType);
   237→        }
   238→        break;
   239→
   240→      case "comparison":
   241→        // 비교 연산 타입 추론
   242→        if (instr.assign_to) {
   243→          this.scope.set(instr.assign_to, "bool");
   244→        }
   245→        break;
   246→
   247→      case "property_access":
   248→        // 속성 접근 타입 추론
   249→        if (instr.assign_to) {
   250→          this.scope.set(instr.assign_to, "any");
   251→        }
   252→        break;
   253→
   254→      case "condition":
   255→        // 조건 검사 (선택사항)
   256→        break;
   257→
   258→      case "loop":
   259→        // 범위 검사 (선택사항)
   260→        break;
   261→    }
   262→  }
   263→
   264→  inferType(expr) {
   265→    if (!expr) {
   266→      return "any";
   267→    }
   268→
   269→    // 기본 값 타입
   270→    if (typeof expr === "number") {
   271→      return "i32";
   272→    }
   273→    if (typeof expr === "string") {
   274→      return "string";
   275→    }
   276→    if (typeof expr === "boolean") {
   277→      return "bool";
   278→    }
