   350→
   351→      case "call":
   352→        return this.generateCallInstruction(instr);
   353→
   354→      case "condition":
   355→        return this.generateConditionInstruction(instr);
   356→
   357→      case "loop":
   358→        return this.generateLoopInstruction(instr);
   359→
   360→      case "arithmetic":
   361→        return this.generateArithmeticInstruction(instr);
   362→
   363→      case "comparison":
   364→        return this.generateComparisonInstruction(instr);
   365→
   366→      case "property_access":
   367→        return this.generatePropertyAccessInstruction(instr);
   368→
   369→      case "comment":
   370→        return `; ${instr.text}`;
   371→
   372→      default:
   373→        return null;
   374→    }
   375→  }
   376→
   377→  generateVarDeclaration(instr) {
   378→    let value;
   379→
   380→    // 값이 기본 타입(숫자, 문자열, 불린)이면 직접 처리
   381→    if (typeof instr.value === "number") {
   382→      value = instr.value.toString();
   383→    } else if (typeof instr.value === "string") {
   384→      value = `"${instr.value}"`;
   385→    } else if (typeof instr.value === "boolean") {
   386→      value = instr.value ? "true" : "false";
   387→    } else if (typeof instr.value === "object" && instr.value) {
