   389→      value = this.generateExpression(instr.value);
   390→    } else {
   391→      value = "null";
   392→    }
   393→
   394→    return `(define ${instr.name} ${value})`;
   395→  }
   396→
   397→  generateCallInstruction(instr) {
   398→    const args = instr.args.map((arg) => this.generateExpression(arg)).join(" ");
   399→    const callCode = `(call ${instr.function} ${args})`;
   400→
   401→    if (instr.assign_to) {
   402→      return `(define ${instr.assign_to} ${callCode})`;
   403→    } else {
   404→      return callCode;
   405→    }
   406→  }
   407→
   408→  generateExpression(expr) {
   409→    if (!expr) {
   410→      return "null";
   411→    }
   412→
   413→    // 기본 타입 처리
   414→    if (typeof expr === "number" || typeof expr === "boolean") {
   415→      return expr.toString();
   416→    }
   417→    if (typeof expr === "string") {
   418→      return `"${expr}"`;
   419→    }
   420→
   421→    // 객체/배열 타입 처리
   422→    if (typeof expr !== "object" || !expr.type) {
   423→      return "null";
   424→    }
   425→
   426→    switch (expr.type) {
   427→      case "literal":
   428→        if (expr.value_type === "string") {
   429→          return `"${expr.value}"`;
   430→        }
   431→        return expr.value !== undefined ? expr.value.toString() : "null";
   432→
   433→      case "ref":
   434→        return expr.name;
   435→
   436→      case "arithmetic":
   437→        const left = this.generateExpression(expr.left);
   438→        const right = this.generateExpression(expr.right);
   439→        return `(${expr.operator} ${left} ${right})`;
   440→
   441→      case "comparison":
   442→        const compLeft = this.generateExpression(expr.left);
   443→        const compRight = this.generateExpression(expr.right);
   444→        return `(${expr.operator} ${compLeft} ${compRight})`;
   445→
   446→      case "call":
   447→        const callArgs = expr.args ? expr.args.map((arg) => this.generateExpression(arg)).join(" ") : "";
   448→        return `(call ${expr.function}${callArgs ? ' ' + callArgs : ''})`;
   449→
   450→      case "array":
   451→        if (!expr.elements || expr.elements.length === 0) {
   452→          return "(array)";
   453→        }
   454→        const elements = expr.elements
   455→          .map((e) => this.generateExpression(e))
   456→          .join(" ");
   457→        return `(array ${elements})`;
   458→
   459→      case "object":
   460→        const props = Object.entries(expr.properties)
   461→          .map(([key, value]) => `("${key}" ${this.generateExpression(value)})`)
   462→          .join(" ");
   463→        return `(object ${props})`;
   464→
   465→      case "lambda":
   466→        const params = expr.params ? expr.params.map((p) => typeof p === 'string' ? p : p.name).join(" ") : "";
   467→        const bodyExpr = expr.body
   468→          .map((b) => {
   469→            // Check if it's an instruction or an expression
   470→            if (b.type === "arithmetic" || b.type === "comparison" || b.type === "ref" || b.type === "literal" || b.type === "call") {
   471→              return this.generateExpression(b);
   472→            } else {
   473→              return this.generateInstruction(b);
   474→            }
   475→          })
   476→          .filter((b) => b !== null)
   477→          .join(" ");
   478→        return `(fn (${params}) ${bodyExpr})`;
   479→
   480→      case "property":
   481→        const obj = this.generateExpression(expr.object);
   482→        return `(property ${obj} "${expr.property}")`;
   483→
   484→      case "property_access":
   485→        const objPA = this.generateExpression(expr.object);
   486→        return `(property ${objPA} "${expr.property}")`;
   487→
   488→      case "index":
   489→        const array = this.generateExpression(expr.array);
   490→        const index = this.generateExpression(expr.index);
   491→        return `(index ${array} ${index})`;
   492→
   493→      default:
   494→        return "null";
   495→    }
   496→  }
   497→
   498→  generateConditionInstruction(instr) {
   499→    const test = this.generateExpression(instr.test);
   500→    const thenCode = instr.then
   501→      .map((i) => this.generateInstruction(i))
   502→      .filter((i) => i !== null)
   503→      .join(" ");
   504→    const elseCode = instr.else
   505→      ? instr.else
   506→          .map((i) => this.generateInstruction(i))
   507→          .filter((i) => i !== null)
   508→          .join(" ")
   509→      : "null";
   510→
   511→    return `(if ${test} (do ${thenCode}) (do ${elseCode}))`;
   512→  }
   513→
   514→  generateLoopInstruction(instr) {
   515→    const range = this.generateExpression(instr.range);
   516→    const body = instr.body
   517→      .map((i) => this.generateInstruction(i))
   518→      .filter((i) => i !== null)
   519→      .join(" ");
   520→
   521→    return `(for ${instr.iterator} ${range} (do ${body}))`;
   522→  }
   523→
   524→  generateArithmeticInstruction(instr) {
   525→    const left = this.generateExpression(instr.left);
   526→    const right = this.generateExpression(instr.right);
   527→    const callCode = `(${instr.operator} ${left} ${right})`;
   528→
   529→    if (instr.assign_to) {
   530→      return `(define ${instr.assign_to} ${callCode})`;
   531→    } else {
   532→      return callCode;
   533→    }
   534→  }
   535→
   536→  generateComparisonInstruction(instr) {
   537→    const left = this.generateExpression(instr.left);
   538→    const right = this.generateExpression(instr.right);
   539→    const callCode = `(${instr.operator} ${left} ${right})`;
   540→
   541→    if (instr.assign_to) {
   542→      return `(define ${instr.assign_to} ${callCode})`;
   543→    } else {
   544→      return callCode;
   545→    }
   546→  }
   547→
   548→  generatePropertyAccessInstruction(instr) {
   549→    const obj = this.generateExpression(instr.object);
   550→    const prop = `"${instr.property}"`;
   551→    const callCode = `(property ${obj} ${prop})`;
   552→
   553→    if (instr.assign_to) {
   554→      return `(define ${instr.assign_to} ${callCode})`;
   555→    } else {
   556→      return callCode;
   557→    }
   558→  }
   559→}
   560→
   561→// 내보내기
   562→if (typeof module !== "undefined" && module.exports) {
   563→  module.exports = CLAUDELangCompiler;
   564→}
