    24→
    25→  tokenize() {
    26→    while (this.pos < this.code.length) {
    27→      const char = this.code[this.pos];
    28→
    29→      // 공백 무시
    30→      if (/\s/.test(char)) {
    31→        this.pos++;
    32→        continue;
    33→      }
    34→
    35→      // 주석 무시
    36→      if (char === ';') {
    37→        while (this.pos < this.code.length && this.code[this.pos] !== '\n') {
    38→          this.pos++;
    39→        }
    40→        continue;
    41→      }
    42→
    43→      // 괄호
    44→      if (char === '(' || char === ')') {
    45→        this.tokens.push(char);
    46→        this.pos++;
    47→        continue;
    48→      }
    49→
    50→      // 문자열
    51→      if (char === '"') {
    52→        const str = this.readString();
    53→        this.tokens.push({ type: 'string', value: str });
    54→        continue;
    55→      }
    56→
    57→      // 심볼/숫자
    58→      const symbol = this.readSymbol();
    59→      if (symbol) {
    60→        // 숫자인지 확인
    61→        if (/^-?\d+(\.\d+)?$/.test(symbol)) {
    62→          this.tokens.push({ type: 'number', value: parseFloat(symbol) });
    63→        } else if (symbol === 'true' || symbol === 'false') {
    64→          this.tokens.push({ type: 'boolean', value: symbol === 'true' });
    65→        } else {
    66→          this.tokens.push({ type: 'symbol', value: symbol });
    67→        }
    68→      }
    69→    }
    70→
    71→    return this.tokens;
    72→  }
    73→
    74→  readString() {
    75→    this.pos++; // 시작 따옴표 건너뛰기
    76→    let str = '';
    77→    while (this.pos < this.code.length && this.code[this.pos] !== '"') {
    78→      if (this.code[this.pos] === '\\') {
    79→        this.pos++;
    80→        if (this.pos < this.code.length) {
    81→          switch (this.code[this.pos]) {
    82→            case 'n': str += '\n'; break;
    83→            case 't': str += '\t'; break;
    84→            case 'r': str += '\r'; break;
    85→            case '"': str += '"'; break;
    86→            case '\\': str += '\\'; break;
    87→            default: str += this.code[this.pos];
    88→          }
    89→          this.pos++;
    90→        }
    91→      } else {
    92→        str += this.code[this.pos];
    93→        this.pos++;
    94→      }
    95→    }
    96→    this.pos++; // 끝 따옴표 건너뛰기
    97→    return str;
    98→  }
    99→
   100→  readSymbol() {
   101→    let symbol = '';
   102→    while (this.pos < this.code.length && !/[\s()"]/.test(this.code[this.pos])) {
   103→      symbol += this.code[this.pos];
   104→      this.pos++;
   105→    }
   106→    return symbol;
   107→  }
   108→}
