   110→/**
   111→ * VT 토큰을 AST로 파싱
   112→ */
   113→class VTParser {
   114→  constructor(tokens) {
   115→    this.tokens = tokens;
   116→    this.pos = 0;
   117→  }
   118→
   119→  parse() {
   120→    const expressions = [];
   121→    while (this.pos < this.tokens.length) {
   122→      const expr = this.parseExpression();
   123→      if (expr !== null) {
   124→        expressions.push(expr);
   125→      }
   126→    }
   127→    return { type: 'program', expressions };
   128→  }
   129→
   130→  parseExpression() {
   131→    const token = this.peek();
   132→    if (token === null) return null;
   133→
   134→    if (token === '(') {
   135→      return this.parseList();
   136→    } else {
   137→      return this.parseAtom();
   138→    }
   139→  }
   140→
   141→  parseList() {
   142→    this.consume('(');
   143→    const elements = [];
   144→    while (this.peek() !== ')') {
   145→      elements.push(this.parseExpression());
   146→    }
   147→    this.consume(')');
   148→    return { type: 'list', elements };
   149→  }
   150→
   151→  parseAtom() {
   152→    const token = this.next();
   153→    if (token === null) return null;
   154→
   155→    if (typeof token === 'object') {
   156→      return {
   157→        type: 'literal',
   158→        value: token.value,
   159→        literalType: token.type
   160→      };
   161→    } else {
   162→      return {
   163→        type: 'symbol',
   164→        value: token
   165→      };
   166→    }
   167→  }
   168→
   169→  peek() {
   170→    if (this.pos < this.tokens.length) {
   171→      return this.tokens[this.pos];
   172→    }
   173→    return null;
   174→  }
   175→
   176→  next() {
   177→    if (this.pos < this.tokens.length) {
   178→      return this.tokens[this.pos++];
   179→    }
   180→    return null;
   181→  }
   182→
   183→  consume(expected) {
   184→    const token = this.next();
   185→    if (token !== expected) {
   186→      throw new Error(`Expected '${expected}', got '${token}'`);
   187→    }
   188→  }
   189→}
