   201→  /**
   202→   * 내장 함수 초기화
   203→   */
   204→  initializeBuiltins() {
   205→    // I/O
   206→    this.functions.set('print', (value) => {
   207→      process.stdout.write(String(value));
   208→      return null;
   209→    });
   210→
   211→    this.functions.set('println', (value) => {
   212→      console.log(String(value));
   213→      return null;
   214→    });
   215→
   216→    // 산술 연산
   217→    this.functions.set('+', (...args) => {
   218→      return args.reduce((a, b) => a + b, 0);
   219→    });
   220→
   221→    this.functions.set('-', (...args) => {
   222→      if (args.length === 1) return -args[0];
   223→      return args.reduce((a, b) => a - b);
   224→    });
   225→
   226→    this.functions.set('*', (...args) => {
   227→      return args.reduce((a, b) => a * b, 1);
   228→    });
   229→
   230→    this.functions.set('/', (...args) => {
   231→      return args.reduce((a, b) => a / b);
   232→    });
   233→
   234→    this.functions.set('%', (a, b) => {
   235→      return a % b;
   236→    });
   237→
   238→    // 비교 연산
   239→    this.functions.set('=', (a, b) => a === b);
   240→    this.functions.set('!=', (a, b) => a !== b);
   241→    this.functions.set('<', (a, b) => a < b);
   242→    this.functions.set('>', (a, b) => a > b);
   243→    this.functions.set('<=', (a, b) => a <= b);
   244→    this.functions.set('>=', (a, b) => a >= b);
   245→
   246→    // 논리 연산
   247→    this.functions.set('and', (...args) => {
   248→      return args.reduce((a, b) => a && b, true);
   249→    });
   250→
   251→    this.functions.set('or', (...args) => {
   252→      return args.reduce((a, b) => a || b, false);
   253→    });
   254→
   255→    this.functions.set('not', (a) => {
   256→      return !a;
   257→    });
   258→
   259→    // 타입 관련
   260→    this.functions.set('array', (...args) => {
   261→      return args;
   262→    });
   263→
   264→    this.functions.set('object', (...args) => {
   265→      const obj = {};
   266→      for (let i = 0; i < args.length; i += 2) {
   267→        if (i + 1 < args.length) {
   268→          obj[args[i]] = args[i + 1];
   269→        }
   270→      }
   271→      return obj;
   272→    });
   273→
   274→    // 배열 함수
   275→    this.functions.set('Array.length', (arr) => {
   276→      return Array.isArray(arr) ? arr.length : 0;
   277→    });
   278→
   279→    this.functions.set('Array.get', (arr, index) => {
   280→      return Array.isArray(arr) ? arr[index] : null;
   281→    });
   282→
   283→    this.functions.set('Array.set', (arr, index, value) => {
   284→      if (Array.isArray(arr)) {
   285→        arr[index] = value;
   286→      }
   287→      return arr;
   288→    });
   289→
   290→    this.functions.set('Array.push', (arr, value) => {
