   364→
   365→    // Math 함수
   366→    this.functions.set('Math.sqrt', (x) => Math.sqrt(x));
   367→    this.functions.set('Math.abs', (x) => Math.abs(x));
   368→    this.functions.set('Math.pow', (x, y) => Math.pow(x, y));
   369→    this.functions.set('Math.floor', (x) => Math.floor(x));
   370→    this.functions.set('Math.ceil', (x) => Math.ceil(x));
   371→    this.functions.set('Math.round', (x) => Math.round(x));
   372→    this.functions.set('Math.sin', (x) => Math.sin(x));
   373→    this.functions.set('Math.cos', (x) => Math.cos(x));
   374→    this.functions.set('Math.tan', (x) => Math.tan(x));
   375→    this.functions.set('Math.max', (...args) => Math.max(...args));
   376→    this.functions.set('Math.min', (...args) => Math.min(...args));
   377→
   378→    // FileSystem 함수
   379→    const fs = require('fs');
   380→    this.functions.set('FS.read', (path) => {
   381→      try {
   382→        return fs.readFileSync(String(path), 'utf8');
   383→      } catch (e) {
   384→        return null;
   385→      }
   386→    });
   387→
   388→    this.functions.set('FS.write', (path, content) => {
   389→      try {
   390→        fs.writeFileSync(String(path), String(content), 'utf8');
   391→        return true;
   392→      } catch (e) {
   393→        return false;
   394→      }
   395→    });
   396→
   397→    this.functions.set('FS.exists', (path) => {
   398→      try {
   399→        return fs.existsSync(String(path));
   400→      } catch (e) {
   401→        return false;
   402→      }
   403→    });
   404→
   405→    // Type checking
   406→    this.functions.set('typeof', (value) => {
   407→      if (value === null) return 'null';
   408→      if (Array.isArray(value)) return 'array';
   409→      return typeof value;
   410→    });
   411→
   412→    this.functions.set('is_null', (value) => value === null);
   413→    this.functions.set('is_array', (value) => Array.isArray(value));
   414→    this.functions.set('is_object', (value) => {
   415→      return typeof value === 'object' && value !== null && !Array.isArray(value);
   416→    });
   417→
   418→    // Property access
   419→    this.functions.set('property', (obj, prop) => {
   420→      if (obj === null || obj === undefined) return null;
   421→      return obj[prop];
   422→    });
   423→
   424→    this.functions.set('index', (arr, idx) => {
   425→      if (Array.isArray(arr)) return arr[idx];
   426→      return null;
   427→    });
   428→  }
   429→
   430→  /**
   431→   * AST 평가
   432→   */
   433→  evaluate(ast) {
   434→    if (!ast) return null;
   435→
   436→    if (ast.type === 'program') {
   437→      let result = null;
   438→      for (const expr of ast.expressions) {
   439→        result = this.evaluateExpression(expr);
   440→      }
   441→      return result;
   442→    }
   443→
   444→    return this.evaluateExpression(ast);
   445→  }
   446→
   447→  evaluateExpression(expr) {
   448→    if (!expr) return null;
   449→
   450→    switch (expr.type) {
   451→      case 'literal':
   452→        return expr.value;
   453→
   454→      case 'symbol':
   455→        // 변수 참조
   456→        if (this.memory.has(expr.value)) {
   457→          return this.memory.get(expr.value);
   458→        }
   459→        throw new Error(`Undefined variable: ${expr.value}`);
   460→
   461→      case 'list':
   462→        return this.evaluateList(expr);
   463→
   464→      default:
   465→        return null;
   466→    }
   467→  }
   468→
   469→  evaluateList(expr) {
   470→    if (!expr.elements || expr.elements.length === 0) {
   471→      return [];
   472→    }
   473→
   474→    const first = expr.elements[0];
   475→    if (!first) return null;
   476→
   477→    // 특별한 형식 (define, if, do, for 등)
   478→    if (first.type === 'symbol') {
   479→      const opName = first.value;
   480→
   481→      if (opName === 'define') {
   482→        return this.evaluateDefine(expr.elements.slice(1));
   483→      }
   484→
   485→      if (opName === 'if') {
   486→        return this.evaluateIf(expr.elements.slice(1));
   487→      }
   488→
   489→      if (opName === 'do') {
   490→        return this.evaluateDo(expr.elements.slice(1));
   491→      }
   492→
   493→      if (opName === 'for') {
   494→        return this.evaluateFor(expr.elements.slice(1));
   495→      }
   496→
   497→      if (opName === 'call') {
   498→        return this.evaluateCall(expr.elements.slice(1));
   499→      }
   500→
   501→      if (opName === 'lambda' || opName === 'fn') {
   502→        return this.evaluateLambda(expr.elements.slice(1));
   503→      }
   504→
   505→      // 함수 호출 (첫 요소가 함수명)
   506→      if (this.functions.has(opName)) {
   507→        const args = expr.elements.slice(1).map(e => this.evaluateExpression(e));
   508→        return this.functions.get(opName)(...args);
   509→      }
   510→    }
   511→
   512→    // 연산자 호출
   513→    if (first.type === 'symbol' && this.functions.has(first.value)) {
   514→      const fn = this.functions.get(first.value);
   515→      const args = expr.elements.slice(1).map(e => this.evaluateExpression(e));
   516→      return fn(...args);
   517→    }
   518→
   519→    return null;
   520→  }
   521→
   522→  evaluateDefine(args) {
   523→    if (args.length < 2) {
   524→      throw new Error('define requires at least 2 arguments');
   525→    }
   526→
   527→    const nameExpr = args[0];
   528→    const valueExpr = args[1];
   529→
   530→    if (nameExpr.type !== 'symbol') {
   531→      throw new Error('define: first argument must be a symbol');
   532→    }
   533→
   534→    const value = this.evaluateExpression(valueExpr);
   535→    this.memory.set(nameExpr.value, value);
   536→    return value;
   537→  }
   538→
   539→  evaluateIf(args) {
   540→    if (args.length < 2) {
   541→      throw new Error('if requires at least 2 arguments');
   542→    }
   543→
   544→    const test = this.evaluateExpression(args[0]);
   545→    if (test) {
   546→      return this.evaluateExpression(args[1]);
   547→    } else if (args.length >= 3) {
   548→      return this.evaluateExpression(args[2]);
   549→    }
   550→    return null;
   551→  }
   552→
   553→  evaluateDo(args) {
   554→    let result = null;
   555→    for (const expr of args) {
   556→      result = this.evaluateExpression(expr);
   557→    }
   558→    return result;
   559→  }
   560→
   561→  evaluateFor(args) {
   562→    if (args.length < 3) {
   563→      throw new Error('for requires at least 3 arguments');
   564→    }
   565→
   566→    const iteratorExpr = args[0];
   567→    const rangeExpr = args[1];
   568→    const bodyExpr = args[2];
   569→
   570→    if (iteratorExpr.type !== 'symbol') {
   571→      throw new Error('for: first argument must be a symbol');
   572→    }
   573→
   574→    const range = this.evaluateExpression(rangeExpr);
   575→    let result = null;
   576→
   577→    if (Array.isArray(range)) {
   578→      for (const item of range) {
   579→        this.memory.set(iteratorExpr.value, item);
   580→        result = this.evaluateExpression(bodyExpr);
   581→      }
   582→    }
   583→
   584→    return result;
   585→  }
   586→
   587→  evaluateCall(args) {
   588→    if (args.length < 1) {
   589→      throw new Error('call requires at least 1 argument');
   590→    }
   591→
   592→    const funcExpr = args[0];
   593→    if (funcExpr.type !== 'symbol') {
   594→      throw new Error('call: function name must be a symbol');
   595→    }
   596→
   597→    const funcName = funcExpr.value;
   598→    if (!this.functions.has(funcName)) {
   599→      throw new Error(`Unknown function: ${funcName}`);
   600→    }
   601→
   602→    const fn = this.functions.get(funcName);
   603→    const callArgs = args.slice(1).map(e => this.evaluateExpression(e));
   604→    return fn(...callArgs);
   605→  }
   606→
   607→  evaluateLambda(args) {
   608→    // Lambda 함수는 단순히 저장
   609→    return {
   610→      type: 'lambda',
   611→      params: args[0],
   612→      body: args.slice(1)
   613→    };
   614→  }
   615→
   616→  /**
   617→   * 함수 등록
   618→   */
   619→  registerFunction(name, fn) {
   620→    this.functions.set(name, fn);
   621→  }
   622→
   623→  /**
   624→   * 메모리 상태 조회
   625→   */
   626→  getMemory() {
   627→    return Object.fromEntries(this.memory);
   628→  }
   629→
   630→  /**
   631→   * 메모리 초기화
   632→   */
   633→  clearMemory() {
   634→    this.memory.clear();
   635→  }
   636→}
