   638→/**
   639→ * VT Runtime Bridge - 메인 인터페이스
   640→ */
   641→class VTRuntimeBridge {
   642→  constructor() {
   643→    this.evaluator = new VTEvaluator();
   644→  }
   645→
   646→  /**
   647→   * VT 코드 실행
   648→   * @param {string} vtCode - VT 코드 (스킴 형식)
   649→   * @returns {Object} {success, result, memory, errors}
   650→   */
   651→  execute(vtCode) {
   652→    try {
   653→      // 1. 토크나이즈
   654→      const tokenizer = new VTTokenizer(vtCode);
   655→      const tokens = tokenizer.tokenize();
   656→
   657→      // 2. 파싱
   658→      const parser = new VTParser(tokens);
   659→      const ast = parser.parse();
   660→
   661→      // 3. 평가
   662→      const result = this.evaluator.evaluate(ast);
   663→
   664→      // 4. 메모리 상태 반환
   665→      return {
   666→        success: true,
   667→        result: result,
   668→        memory: this.evaluator.getMemory(),
   669→        errors: []
   670→      };
   671→    } catch (error) {
   672→      return {
   673→        success: false,
   674→        result: null,
   675→        memory: this.evaluator.getMemory(),
   676→        errors: [error.message]
   677→      };
   678→    }
   679→  }
   680→
   681→  /**
   682→   * 메모리 상태 조회
   683→   */
   684→  getMemory() {
   685→    return this.evaluator.getMemory();
   686→  }
   687→
   688→  /**
   689→   * 메모리 초기화
   690→   */
   691→  clearMemory() {
