   708→  executeJSON(claudelangJson, compiler) {
   709→    try {
   710→      // 컴파일
   711→      const compiled = compiler.compile(claudelangJson);
   712→      if (!compiled.success) {
   713→        return {
   714→          success: false,
   715→          result: null,
   716→          memory: {},
   717→          errors: compiled.errors
   718→        };
   719→      }
   720→
