    60→      }
    61→
    62→      // 실행
    63→      const result = this.bridge.execute(compiled.code);
    64→
    65→      if (!result.success) {
    66→        log('red', `✗ ${name}`);
    67→        log('red', `  Execution failed: ${result.errors.join(', ')}`);
    68→        this.failCount++;
    69→        this.results.push({
    70→          name,
    71→          status: 'FAILED',
    72→          reason: `Execution: ${result.errors[0]}`
    73→        });
    74→        return;
    75→      }
    76→
    77→      // 성공
    78→      log('green', `✓ ${name}`);
    79→      this.passCount++;
    80→      this.results.push({
    81→        name,
    82→        status: 'PASSED',
    83→        result: result.result,
    84→        memory: result.memory
    85→      });
    86→
    87→      // 메모리 초기화
