     1→/**
     2→ * CLAUDELang v6.0 Cached Compiler
     3→ * 컴파일 결과 캐싱을 통한 성능 최적화
     4→ *
     5→ * 최적화:
     6→ * 1. 전체 AST 캐싱
     7→ * 2. 부분 컴파일 결과 캐싱
     8→ * 3. 함수 시그니처 캐싱
     9→ */
    10→
    11→const crypto = require("crypto");
    12→const CLAUDELangCompiler = require("./compiler.js");
    13→
    14→class CachedCLAUDELangCompiler extends CLAUDELangCompiler {
    15→  constructor(maxCacheSize = 1000) {
    16→    super();
    17→    this.cache = new Map(); // 컴파일 결과 캐시
    18→    this.astCache = new Map(); // AST 파싱 결과 캐시
    19→    this.maxCacheSize = maxCacheSize;
    20→    this.cacheHits = 0;
    21→    this.cacheMisses = 0;
    22→  }
    23→
    24→  /**
    25→   * 입력 프로그램의 해시 생성
    26→   * 동일한 입력을 빠르게 식별하기 위함
    27→   */
    28→  generateHash(data) {
    29→    const str = JSON.stringify(data);
    30→    return crypto.createHash("md5").update(str).digest("hex");
    31→  }
    32→
    33→  /**
    34→   * 캐시 크기 관리 (LRU 정책)
    35→   */
    36→  evictIfNeeded() {
    37→    if (this.cache.size > this.maxCacheSize) {
    38→      // 가장 오래된 항목 제거
    39→      const firstKey = this.cache.keys().next().value;
    40→      this.cache.delete(firstKey);
    41→    }
    42→  }
    43→
    44→  /**
    45→   * 최적화된 컴파일 (캐싱 포함)
    46→   */
    47→  compile(claudelangJson) {
    48→    // 입력 해시 생성
    49→    const hash = this.generateHash(claudelangJson);
    50→
    51→    // 캐시 확인
    52→    if (this.cache.has(hash)) {
    53→      this.cacheHits++;
    54→      return this.cache.get(hash);
    55→    }
    56→
    57→    this.cacheMisses++;
    58→
    59→    // 원본 컴파일 실행
    60→    const result = super.compile(claudelangJson);
    61→
    62→    // 결과 캐싱
    63→    this.cache.set(hash, result);
    64→    this.evictIfNeeded();
    65→
    66→    return result;
    67→  }
    68→
    69→  /**
    70→   * 검증만 캐싱 (빠른 검증)
    71→   */
    72→  validateCached(obj) {
    73→    const hash = this.generateHash(obj);
    74→    const cacheKey = `validate_${hash}`;
    75→
    76→    if (this.cache.has(cacheKey)) {
    77→      return true; // 이미 검증됨
    78→    }
    79→
    80→    try {
    81→      super.validate(obj);
    82→      this.cache.set(cacheKey, { validated: true });
    83→      return true;
    84→    } catch (error) {
    85→      return false;
    86→    }
    87→  }
    88→
    89→  /**
    90→   * 부분 AST 캐싱을 통한 개별 명령어 컴파일
    91→   */
    92→  compileInstruction(instruction) {
    93→    const hash = this.generateHash(instruction);
    94→    const cacheKey = `instr_${hash}`;
    95→
    96→    if (this.cache.has(cacheKey)) {
    97→      this.cacheHits++;
    98→      return this.cache.get(cacheKey);
    99→    }
   100→
   101→    this.cacheMisses++;
   102→
   103→    try {
   104→      const result = this.generateInstruction(instruction);
   105→      this.cache.set(cacheKey, result);
   106→      this.evictIfNeeded();
   107→      return result;
   108→    } catch (error) {
   109→      return null;
   110→    }
   111→  }
   112→
   113→  /**
   114→   * 캐시 통계
   115→   */
   116→  getCacheStats() {
   117→    const total = this.cacheHits + this.cacheMisses;
   118→    const hitRate = total === 0 ? 0 : (this.cacheHits / total) * 100;
   119→
   120→    return {
   121→      cacheSize: this.cache.size,
   122→      maxCacheSize: this.maxCacheSize,
   123→      hits: this.cacheHits,
   124→      misses: this.cacheMisses,
   125→      total: total,
   126→      hitRate: hitRate.toFixed(2) + "%",
   127→      efficiency: ((this.cacheHits * 100) / (total || 1)).toFixed(2),
   128→    };
   129→  }
   130→
   131→  /**
   132→   * 캐시 초기화
   133→   */
   134→  clearCache() {
   135→    this.cache.clear();
   136→    this.cacheHits = 0;
   137→    this.cacheMisses = 0;
   138→  }
   139→
   140→  /**
   141→   * 캐시 상태 출력
   142→   */
   143→  printCacheStats() {
   144→    const stats = this.getCacheStats();
   145→    console.log("\n");
   146→    console.log("╔" + "═".repeat(50) + "╗");
   147→    console.log("║" + " Cache Statistics".padEnd(50) + "║");
   148→    console.log("╠" + "═".repeat(50) + "╣");
   149→    console.log(`║ Cache Size: ${stats.cacheSize}/${stats.maxCacheSize}`.padEnd(51) + "║");
   150→    console.log(`║ Hits: ${stats.hits}, Misses: ${stats.misses}`.padEnd(51) + "║");
   151→    console.log(`║ Hit Rate: ${stats.hitRate}`.padEnd(51) + "║");
   152→    console.log("╚" + "═".repeat(50) + "╝\n");
   153→  }
   154→}
   155→
   156→module.exports = CachedCLAUDELangCompiler;
   157→

